#!/bin/bash
# This script generates the Terraform files to set up TMA for a new stamp.

set -e

if [ $# -ne 3 ]; then
    echo "Usage: $0 STAMP_NAME STAMP_ENV AZURE_REGION"
    echo "e.g. $0 prod-weu-01 prod westeurope"
    exit 1
fi

export STAMP_NAME=$1
export STAMP_NAME_UNDERSCORED=$(echo $STAMP_NAME | tr '-' '_')
export STAMP_ENV=$2
export AZURE_REGION=$3
TEMPLATE_DIR="templates/terraform"
DEST_DIR="../../terraform"

if [ "$STAMP_ENV" = "prod" ]; then
    # production subscription
    export AZURE_SUBSCRIPTION="56eeaa83-e372-4311-a873-55e3806dcc42"
    export STAMP_ENV_VERBOSE="production"
    export UNAUTH_ACCESS_ALERT_SEVERITY="1"
else
    # staging subscription
    export AZURE_SUBSCRIPTION="a0231bbd-fed8-4abc-bc8d-dc92d3e358bf"
    export STAMP_ENV_VERBOSE="staging"
    export UNAUTH_ACCESS_ALERT_SEVERITY="2"
fi

case $STAMP_NAME in
  prod-ae-01)
    export PAGERDUTY_INTEGRATION_KEY="68659280db144d09d05aeb36e6d52b78"
    ;;
  prod-cus-01)
    export PAGERDUTY_INTEGRATION_KEY="2b18e31051904604c0ab1ae18fd85f37"
    ;;
  prod-sdc-01)
    export PAGERDUTY_INTEGRATION_KEY="dc7c9764bc984101d0f0e8a32bdb5e29"
    ;;
  prod-weu-01)
    export PAGERDUTY_INTEGRATION_KEY="b3371bdb83b64200d03fc19f47932ffb"
    ;;
  production)
    export PAGERDUTY_INTEGRATION_KEY="4e9f873a09e84c04c04c6f0259935711"
    ;;
  staging | staff-wus2-01 | test-cnc-01 )
    export PAGERDUTY_INTEGRATION_KEY="160074b5831f4e00c0b38899f4715374"
    ;;
  *)
    echo "No PagerDuty integration key defined for stamp ${STAMP_NAME}"
    exit 1
    ;;
esac

# Loop through each template file in the source directory
for template_file in "$TEMPLATE_DIR"/*; do
    # Get the filename without the path
    filename=$(basename "$template_file")
    
    # Set the destination file path
    dest_file="$DEST_DIR/$STAMP_NAME/$filename"

    # Create the destination directory if it doesn't exist
    mkdir -p "$(dirname "$dest_file")"
    
    # Render the template using envsubst and write it to the destination file
    (cat <<EOF
/*
DO NOT EDIT THIS FILE MANUALLY. PLEASE USE THE GENERATOR SCRIPTS LOCATED IN config/generator.
*/
EOF
    envsubst) < "$template_file" > "$dest_file"
    
    echo "Rendered $template_file to $dest_file"
done
